int a,b;
void pushToFreq(int frequence){
    for(int i=0;i&lt;frequence;i++)
        freq.push_back(frequence);
}
void translateToFreq(){
    int last=0;
    int count=0;
    bool first=true;
    for(int i=0;i&lt;ori.size();i++){
        if(first){
          last=ori[i];
            count=1;
            first=false;
            continue;
        }
        if(last==ori[i]){
           count++;
        }
        else{
            pushToFreq(count);
            last=ori[i];
            count=1;
        }
    }
    pushToFreq(count);
}
