        st.buildTree();
        for(int j=0;j&lt;Q;j++){
            cin&gt;&gt;a&gt;&gt;b;
            cout&lt;&lt;st.query(a-1,b-1)&lt;&lt;endl;
        }
    }
    return 0;
}
