int v[100000];
int N,K,a,b;
char ch;
class SegmentTree{
private:
    short st[400001];
    int left(int p){return p&lt;&lt;1;}
    int right(int p){return (p&lt;&lt;1)+1;};
    void build(int p,int L,int R){
        if(L==R){
            if(v[L]&gt;0)
             st[p]=1;
            else if(v[L]&lt;0)
             st[p]=-1;
            else
             st[p]=0;
        }
        else{
            build(left(p),L,(L+R)/2);
            build(right(p),(L+R)/2+1,R);
            int l=st[left(p)];
            int r=st[right(p)];
            st[p]=l*r;
        }
    }
    int rmq(int p,int L,int R,int i,int j){
        if(i&gt;R||j&lt;L)
            return -INFINITY;
        if(i&lt;=L&&R&lt;=j){
            return st[p];
        }
        int l=rmq(left(p),L,(L+R)/2,i,j);
        int r=rmq(right(p),(L+R)/2+1,R,i,j);
        if(l==-INFINITY)return r;
        if(r==-INFINITY)return l;
        return l*r;
    }
public:
    char query(int i,int j){
        int k=rmq(1,0,N-1,i,j);
        if(k&gt;0)
            return '+';
        else if(k&lt;0)
            return '-';
        else
            return '0';
    }
    void update(int p,int L,int R,int i){
        if(!(L&lt;=i&&i&lt;=R))
            return;
        if(L==R){
            if(v[L]&gt;0)
             st[p]=1;
            else if(v[L]&lt;0)
             st[p]=-1;
            else
             st[p]=0;
            return;
        }
        update(left(p),L,(L+R)/2,i);
        update(right(p),(L+R)/2+1,R,i);
        st[p]=st[left(p)]*st[right(p)];
    }
    void buildTree(){
        build(1,0,N-1);
    }
};
SegmentTree st;
int main(){
    redirect();
    while(cin&gt;&gt;N&gt;&gt;K){
        for(int i=0;i&lt;N;i++)
            cin&gt;&gt;v[i];
        st.buildTree();
        for(int i=0;i&lt;K;i++){
            cin&gt;&gt;ch&gt;&gt;a&gt;&gt;b;
            if(ch=='C'){
                v[a-1]=b;
                st.update(1,0,N-1,a-1);
            }
            else{
                cout&lt;&lt;st.query(a-1,b-1);
            }
        }
        cout&lt;&lt;endl;
    }
    return 0;
}

