int Direction(Point target,Point p1,Point p2)
{
Point v1,v2;
v1.x=p1.x-target.x,
v1.y=p1.y-target.y,
v2.x=p2.x-target.x,
v2.y=p2.y-target.y;
return Cross_Product(v1,v2);
